namespace ghidra.app.plugin.core.debug.utils;




using ghidra.framework.model;
using ghidra.framework.model;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;
using utility.function;

public class ManagedDomainObject<T> : AutoCloseable where T : DomainObject {
	public static readonly Cleaner CLEANER = Cleaner.create();

	private static class ObjectState<T> : Runnable where T : DomainObject {
		private T obj;

		/* @Override */
		public void run() {
			if (obj.getConsumerList().contains(this)) {
				obj.release(this);
			}
		}

		public T get() {
			if (!obj.getConsumerList().contains(this)) {
				throw new IllegalStateException("Domain object is closed");
			}
			return obj;
		}
	}

	private ObjectState<T> state = new();

	public ManagedDomainObject(DomainFile file, Class<T> type, TaskMonitor monitor)
    {
		state.obj = type.cast(file.getDomainObject(state, true, false, monitor));
		CLEANER.register(this, state);
	}

	public <E extends Exception> ManagedDomainObject(ExceptionalFunction<object, T, E> supplier)
    {
		state.obj = supplier.apply(state);
		CLEANER.register(this, state);
	}

	/* @Override */
	public void close() {
		state.run();
	}

	public T get() {
		return state.get();
	}
}
